import React, { useEffect, useState } from 'react';
import { supabase } from '../supabase';
import { useNavigate } from 'react-router-dom';

function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);

  useEffect(() => {
    const getCurrentUser = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      setUser(user);
    };
    getCurrentUser();
  }, []);

  const handleSignOut = async () => {
    try {
      await supabase.auth.signOut();
      window.location.replace('/login');
    } catch (error) {
      console.error('Error signing out:', error);
    }
  };

  return (
    <div className="relative min-h-screen bg-gray-100 p-8" style={{ zIndex: 1 }}>
      <div className="relative max-w-4xl mx-auto bg-white rounded-lg shadow-lg p-8" style={{ zIndex: 2 }}>
        <div className="relative flex justify-between items-center mb-8" style={{ zIndex: 3 }}>
          <h1 className="text-2xl font-bold">Welcome, {user?.email}!</h1>
          <button
            onClick={handleSignOut}
            className="relative bg-red-600 text-white px-4 py-2 rounded-md hover:bg-red-700 transition-colors cursor-pointer"
            style={{ zIndex: 10 }}
          >
            Sign Out
          </button>
        </div>
        <div className="relative bg-blue-50 border border-blue-200 rounded-lg p-6" style={{ zIndex: 2 }}>
          <h2 className="text-xl font-semibold mb-4">Getting Started</h2>
          <p className="text-gray-700">
            Welcome to your dashboard! You've successfully logged in to your account.
          </p>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
